<script setup lang="ts">
import type { ApiEnvelope } from '~/types/api'
import type { Plan } from '~/types/billing'
import { money } from '~/utils/billing'
useSeoPage('Pricing', 'Choose a 247URL plan for your links and workflows.', '/pricing')
const yearly = ref(false)
const { request } = useApi()
const { data, pending, error, refresh } = await useAsyncData('public-plans',()=>request<ApiEnvelope<Plan[]>>('plans'))
</script>
<template><div><section class="border-b border-border bg-surface"><div class="container-shell py-20 text-center"><p class="eyebrow">Simple, transparent pricing</p><h1 class="mx-auto mt-4 max-w-3xl text-5xl font-bold tracking-tight sm:text-6xl">Choose the plan that<br><span class="text-brand">fits your links.</span></h1><p class="mx-auto mt-5 max-w-xl text-lg text-text-secondary">Start free. Choose more as your workflow grows.</p><div class="mt-8 inline-flex rounded-lg border border-border bg-surface2 p-1" role="group" aria-label="Billing interval"><button class="rounded-md px-5 py-2 text-sm" :class="!yearly?'bg-surface shadow-xs':''" :aria-pressed="!yearly" @click="yearly=false">Monthly</button><button class="rounded-md px-5 py-2 text-sm" :class="yearly?'bg-surface shadow-xs':''" :aria-pressed="yearly" @click="yearly=true">Yearly</button></div></div></section><section class="container-shell py-16"><LoadingState v-if="pending"/><div v-else-if="error" class="surface p-8 text-center" role="alert">Pricing is temporarily unavailable. <button class="text-brand" @click="refresh()">Try again</button></div><div v-else class="grid gap-6 md:grid-cols-3"><article v-for="plan in data?.data" :key="plan.id" class="surface flex flex-col p-7"><p class="eyebrow">{{ plan.is_default?'Get started':'Grow with 247URL' }}</p><h2 class="mt-3 text-xl font-semibold">{{ plan.name }}</h2><p class="mt-5 text-4xl font-bold">{{ money(yearly?plan.yearly_price:plan.monthly_price,plan.currency) }}<span v-if="(yearly?plan.yearly_price:plan.monthly_price)!==null" class="text-xs font-normal text-text-muted"> / {{ yearly?'year':'month' }}</span></p><p class="mt-4 min-h-12 text-text-secondary">{{ plan.description }}</p><NuxtLink :to="plan.is_default?'/register':(yearly?plan.checkout_yearly:plan.checkout_monthly)?`/dashboard/billing?plan=${plan.id}`:'/contact'" class="btn-primary mt-6">{{ plan.is_default?'Create free account':(yearly?plan.checkout_yearly:plan.checkout_monthly)?'Choose plan':'Contact us' }}</NuxtLink><p v-if="!plan.is_default && !(yearly?plan.checkout_yearly:plan.checkout_monthly)" class="mt-3 text-center text-xs text-text-muted">Contact us to arrange this plan.</p><ul class="mt-7 space-y-3 border-t border-border pt-6 text-sm text-text-secondary"><li>{{ plan.link_limit===null?'Unlimited':plan.link_limit }} total links</li><li v-for="feature in plan.features" :key="feature"><span class="mr-2 text-success">✓</span>{{ feature }}</li></ul></article></div><p v-if="data && !data.data.length" class="py-12 text-center">No public plans are available. <NuxtLink to="/contact" class="text-brand">Contact us</NuxtLink>.</p></section></div></template>
